// Update the cached styles of the Nextcloud server for all versions the documentation can simulate.
//
// Usage: node docs/.vitepress/scripts/update-server-styles.mjs <path to a nextcloud/server checkout>
//
// The checkout needs the stable branches as `origin/stableXX` and the dependencies of `master` installed
// (`3rdparty` and `vendor-bin/phpunit`), as the dark theme is generated by the theming app using PHP.
// All other styles are compiled files of the server repository.

/* eslint-disable no-console -- command line script */

import { execFileSync } from 'node:child_process'
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import { NEXTCLOUD_VERSIONS } from '../runtime/nextcloudVersion.js'

const SCRIPTS = fileURLToPath(new URL('.', import.meta.url))
const ASSETS = resolve(SCRIPTS, '../../assets')

/**
 * Get the server branch of a documentation version
 *
 * @param {string} id - The id of the version
 */
const branchOf = (id) => (id === 'upcoming' ? 'master' : `stable${id}`)

/**
 * Render CSS variables as rule
 *
 * @param {string} selector - The selector of the rule
 * @param {Record<string, string>} variables - The variables
 */
const toCss = (selector, variables) => `${selector} {\n${Object.entries(variables).map(([name, value]) => `  ${name}: ${value};`).join('\n')}\n}\n`

/**
 * Normalize CSS variables for comparison, ignoring comments and formatting
 *
 * @param {string} css - The CSS
 */
function variablesOf(css) {
	return css.replace(/\/\*[\s\S]*?\*\//g, '')
		.split('\n')
		.map((line) => line.trim())
		.filter((line) => line.startsWith('--'))
		.sort()
		.join('\n')
}

const server = process.argv[2]
if (!server) {
	console.error('Usage: node update-server-styles.mjs <path to a nextcloud/server checkout>')
	process.exit(1)
}

/**
 * Read a file of the server repository on a branch
 *
 * @param {string} branch - The branch
 * @param {string} file - The file path
 */
const show = (branch, file) => execFileSync('git', ['-C', server, 'show', `origin/${branch}:${file}`], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })

/**
 * Get the CSS variables of the default and dark theme of a branch
 *
 * @param {string} branch - The branch
 */
function dumpThemes(branch) {
	const tmp = mkdtempSync(join(tmpdir(), 'nc-themes-'))
	try {
		// The theming app of the branch with the autoloaders of the checkout
		execFileSync('sh', ['-c', 'git -C "$0" archive "origin/$1" apps/theming/lib | tar -x -C "$2"', server, branch, tmp])
		// Registered last but prepended, so the theming app of the branch is used instead of the one of the checkout
		writeFileSync(join(tmp, 'bootstrap.php'), `<?php
require ${JSON.stringify(join(server, '3rdparty/autoload.php'))};
require ${JSON.stringify(join(server, 'lib/composer/autoload.php'))};
spl_autoload_register(function (string $class): void {
	$prefix = 'OCA\\\\Theming\\\\';
	if (str_starts_with($class, $prefix)) {
		$file = ${JSON.stringify(join(tmp, 'apps/theming/lib'))} . '/' . str_replace('\\\\', '/', substr($class, strlen($prefix))) . '.php';
		if (file_exists($file)) {
			require $file;
		}
	}
}, true, true);
`)
		const output = join(tmp, 'themes.json')
		execFileSync('php', [
			join(server, 'vendor-bin/phpunit/vendor/bin/phpunit'),
			'--bootstrap',
			join(tmp, 'bootstrap.php'),
			join(SCRIPTS, 'DumpThemesTest.php'),
		], { env: { ...process.env, THEMES_OUTPUT: output }, stdio: ['ignore', 'ignore', 'inherit'] })
		return JSON.parse(readFileSync(output, 'utf8'))
	} finally {
		rmSync(tmp, { recursive: true, force: true })
	}
}

const header = '/** SPDX-FileCopyrightText: Nextcloud GmbH and Nextcloud contributors */\n/** SPDX-License-Identifier: AGPL-3.0-or-later */\n'

for (const { id } of NEXTCLOUD_VERSIONS) {
	const branch = branchOf(id)
	const dir = join(ASSETS, `nextcloud-${id}`)
	mkdirSync(dir, { recursive: true })

	// Compiled styles of the server, the images are served from `docs/assets/img`
	const defaultCss = show(branch, 'apps/theming/css/default.css').replaceAll('/apps/theming/img', '../img')
	writeFileSync(join(dir, 'default.css'), defaultCss)
	writeFileSync(join(dir, 'server.css'), show(branch, 'core/css/server.css').replaceAll('../../dist/icons.css', './icons.css'))
	writeFileSync(join(dir, 'apps.css'), show(branch, 'core/css/apps.css'))
	writeFileSync(join(dir, 'icons.css'), show(branch, 'dist/icons.css'))

	// The dark theme is generated by the server, so it is generated like the default theme is
	const themes = dumpThemes(branch)
	const fixImages = (variables) => Object.fromEntries(Object.entries(variables).map(([name, value]) => [name, value.replaceAll('/apps/theming/img', '../img')]))
	if (variablesOf(toCss(':root', fixImages(themes.default))) !== variablesOf(defaultCss)) {
		throw new Error(`The generated default theme of ${branch} does not match its default.css, the generated dark theme would be wrong`)
	}
	writeFileSync(join(dir, 'dark.css'), header + toCss('[data-theme-dark]', fixImages(themes.dark)))

	console.info(`Updated styles of Nextcloud ${id} from ${branch}`)
}
